// Which Data Partners slides a plan can export, and how they are named. The slides themselves are
// drawn as real layout (DataPartnersSlides.tsx) and captured, never generated by an image model:
// their point is that every figure and logo is exactly the verified one, and an image model
// re-types numbers and redraws logos. Pure, so the rules are tested without rendering.

import type { PartnerEvidence } from "./partnerData";

export type PartnerSlideKind = "partners" | "competitors" | "markets";

export interface PartnerSlideSpec {
  kind: PartnerSlideKind;
  label: string;
  description: string;
}

/** A market table needs a few rows to be worth a slide of its own. */
export const MIN_MARKETS_FOR_SLIDE = 3;

/**
 * The slides this plan has, in deck order. A section the planner hid from the client is never
 * exported, the same rule as the share link.
 */
export function partnerSlides(
  evidence: PartnerEvidence | null | undefined,
  hidden: { dataPartners: boolean; competitive: boolean },
): PartnerSlideSpec[] {
  if (!evidence) return [];
  const out: PartnerSlideSpec[] = [];
  if (!hidden.dataPartners && evidence.datasets.length > 0) {
    out.push({ kind: "partners", label: "Data partners", description: "Logos, verified data points and what each dataset measured" });
  }
  const c = evidence.competitive;
  if (c && !hidden.competitive) {
    if (c.competitors.length > 0 || c.mediaTypes.length > 0) {
      out.push({ kind: "competitors", label: "Competitive spend", description: "Spend by competitor and by media type" });
    }
    if (c.markets.length >= MIN_MARKETS_FOR_SLIDE) {
      out.push({ kind: "markets", label: "Market by market", description: "Who leads competitive spend in each market" });
    }
  }
  return out;
}

/** "gateway_fiber_data_partners_competitive_spend_16x9.png" */
export function partnerSlideFileName(advertiser: string, kind: PartnerSlideKind | "all", ratio: string, ext: "png" | "pdf"): string {
  const base = (advertiser || "plan").toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "") || "plan";
  const part = kind === "all" ? "data_partners" : `data_partners_${kind === "partners" ? "overview" : kind === "competitors" ? "competitive_spend" : "markets"}`;
  return `${base}_${part}_${ratio.replace(":", "x")}.${ext}`;
}

/** Shortens text to fit a slide card, at a word boundary. */
export function clip(text: string, max: number): string {
  const t = String(text ?? "").replace(/\s+/g, " ").trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, max - 1);
  const space = cut.lastIndexOf(" ");
  return `${(space > max * 0.6 ? cut.slice(0, space) : cut).replace(/[,;:.\s]+$/, "")}…`;
}
